queries.sparql:
SELECT ?item (SAMPLE(?en) AS ?itemLabel) (SAMPLE(?pt) AS ?labelPt) (MIN(?when) AS ?date) (SAMPLE(?cls) AS ?typeLabel) (SAMPLE(?links) AS ?sitelinks)
WHERE {
  VALUES ?class { wd:Q40231 }
  VALUES ?where { wd:Q45 wd:Q916 wd:Q1029 wd:Q1011 wd:Q1039 wd:Q1006 wd:Q574 wd:Q14773 }
  ?item wdt:P31/wdt:P279* ?class .
  { ?item wdt:P17 ?where } UNION { ?item wdt:P276 ?where } UNION { ?item wdt:P710 ?where }
  ?item wdt:P585|wdt:P580 ?when .
  FILTER NOT EXISTS { ?item wdt:P131 ?admin }
  FILTER(?when >= "1890-01-01T00:00:00Z"^^xsd:dateTime && ?when < "1900-01-01T00:00:00Z"^^xsd:dateTime)
  OPTIONAL { ?item wikibase:sitelinks ?links }
  OPTIONAL { ?item rdfs:label ?en . FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?pt . FILTER(LANG(?pt) = "pt") }
  OPTIONAL { ?item wdt:P31 ?c . ?c rdfs:label ?cls . FILTER(LANG(?cls) = "en") }
}
GROUP BY ?item
ORDER BY ?date
LIMIT 200

